"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def parse_transcript_log(lines):
    """Parse log lines into transcripts. See SPEC.md section 4."""
    out = []
    for n, line in enumerate(lines, 1):
        text = line.strip()
        if not text or text.startswith("#"):
            continue
        parts = [p.strip() for p in text.split(",")]
        if len(parts) != 3:
            raise ValueError(f"line {n}: expected 3 fields, got {len(parts)}")
        id_, day, flag = parts
        try:
            day = int(day)
        except ValueError:
            raise ValueError(f"line {n}: day is not an integer: {day!r}") from None
        if flag == "1":
            flagged = True
        elif flag == "0":
            flagged = False
        elif flag == "":
            flagged = None
        else:
            raise ValueError(f"line {n}: invalid flagged value: {flag!r}")
        out.append({"id": id_, "day": day, "flagged": flagged})
    return out


def dedupe_transcripts(events):
    """Remove duplicate transcripts. See SPEC.md section 5."""
    seen = {}
    for e in events:
        seen[e["id"]] = e
    return sorted(seen.values(), key=lambda e: (e["day"], e["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Daily counts of flagged transcripts. See SPEC.md section 6."""
    if end_day < start_day:
        return []
    counts = {d: 0 for d in range(start_day, end_day + 1)}
    for e in events:
        if e["flagged"] and e["day"] in counts:
            counts[e["day"]] += 1
    return [counts[d] for d in range(start_day, end_day + 1)]
